package trading.common;

/**
 * A crossover (breakout) event generated by Query 2.
 *
 * @param symbol    symbol ID (e.g. "RDSA.NL")
 * @param windowEnd ISO-8601 timestamp of the window where the crossover was detected
 * @param type      {@link #BUY} (bullish breakout) or {@link #SELL} (bearish breakout)
 * @param ema38     EMA with j=38 at the crossover window
 * @param ema100    EMA with j=100 at the crossover window
 */
public record CrossoverEvent(String symbol, String windowEnd, String type, double ema38, double ema100) {

    /** Bullish breakout: EMA-38 crosses above EMA-100. */
    public static final String BUY = "BUY";

    /** Bearish breakout: EMA-38 crosses below EMA-100. */
    public static final String SELL = "SELL";
}
